BEGIN;
CREATE TABLE IF NOT EXISTS support_knowledge_sources(path text PRIMARY KEY,title text NOT NULL,checksum text NOT NULL,content text NOT NULL,source_updated_at timestamptz NOT NULL,imported_at timestamptz NOT NULL DEFAULT now(),imported_by uuid REFERENCES profiles(id));
ALTER TABLE support_knowledge_sources ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON support_knowledge_sources FROM PUBLIC,anon,authenticated;GRANT ALL ON support_knowledge_sources TO service_role;
CREATE TABLE IF NOT EXISTS support_knowledge_articles(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,category text NOT NULL CHECK(category IN('presentation','accounts','catalog','payments','access','media','assessment','community','support')),language text NOT NULL DEFAULT 'fr',description text NOT NULL DEFAULT '',content jsonb NOT NULL DEFAULT '{}',source_refs jsonb NOT NULL DEFAULT '[]',source_version text NOT NULL DEFAULT '',system_version text NOT NULL,validation_status text NOT NULL DEFAULT 'draft' CHECK(validation_status IN('draft','validated','published','archived')),visibility text NOT NULL DEFAULT 'admin' CHECK(visibility IN('admin','student')),revision int NOT NULL DEFAULT 1,reviewed_at timestamptz,reviewed_by uuid REFERENCES profiles(id),updated_at timestamptz NOT NULL DEFAULT now(),search_document tsvector GENERATED ALWAYS AS(to_tsvector('simple',title||' '||description||' '||content::text)) STORED,
 CHECK(validation_status<>'published' OR(reviewed_at IS NOT NULL AND jsonb_array_length(source_refs)>0))
);
CREATE INDEX IF NOT EXISTS support_help_search ON support_knowledge_articles USING gin(search_document);
ALTER TABLE support_knowledge_articles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON support_knowledge_articles FROM PUBLIC,anon,authenticated;
GRANT SELECT(id,slug,title,category,language,description,content,source_refs,source_version,system_version,validation_status,visibility,revision,reviewed_at,updated_at,search_document) ON support_knowledge_articles TO authenticated;
GRANT ALL ON support_knowledge_articles TO service_role;
DROP POLICY IF EXISTS help_read ON support_knowledge_articles;
CREATE POLICY help_read ON support_knowledge_articles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND email_verified_at IS NOT NULL AND banned_at IS NULL AND(role='admin' OR(validation_status='published' AND visibility='student'))));
CREATE TABLE IF NOT EXISTS support_knowledge_versions(article_id uuid NOT NULL REFERENCES support_knowledge_articles(id),revision int NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(article_id,revision));
ALTER TABLE support_knowledge_versions ENABLE ROW LEVEL SECURITY;REVOKE ALL ON support_knowledge_versions FROM PUBLIC,anon,authenticated;GRANT ALL ON support_knowledge_versions TO service_role;
CREATE OR REPLACE FUNCTION search_support_articles(p_query text,p_category text DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(h)),'[]'::jsonb) FROM (
 SELECT id,slug,title,category,language,description,content,source_refs,source_version,system_version,revision,updated_at
 FROM support_knowledge_articles
 WHERE validation_status='published' AND visibility='student' AND reviewed_at IS NOT NULL
 AND(p_category IS NULL OR category=p_category)
 AND(search_document@@websearch_to_tsquery('simple',left(p_query,300)) OR EXISTS(SELECT 1 FROM regexp_split_to_table(lower(left(p_query,300)),'[^[:alnum:]]+') word WHERE char_length(word)>3 AND lower(title||' '||description||' '||content::text) LIKE '%'||word||'%'))
 ORDER BY ts_rank_cd(search_document,websearch_to_tsquery('simple',left(p_query,300))) DESC,updated_at DESC LIMIT 5
 )h;
$$;
REVOKE ALL ON FUNCTION search_support_articles(text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION search_support_articles(text,text) TO authenticated,service_role;
CREATE TABLE IF NOT EXISTS support_conversation_state(conversation_id uuid PRIMARY KEY REFERENCES conversations(id),owner_id uuid NOT NULL REFERENCES profiles(id),issue jsonb NOT NULL DEFAULT '{}',last_message_at timestamptz NOT NULL,last_message_id uuid NOT NULL REFERENCES messages(id),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE support_conversation_state ENABLE ROW LEVEL SECURITY;REVOKE ALL ON support_conversation_state FROM PUBLIC,anon,authenticated;GRANT ALL ON support_conversation_state TO service_role;
CREATE TABLE IF NOT EXISTS support_ai_runs(message_id uuid PRIMARY KEY REFERENCES messages(id),conversation_id uuid NOT NULL REFERENCES conversations(id),claim_id uuid NOT NULL,epoch bigint NOT NULL,status text NOT NULL CHECK(status IN('processing','completed','failed','cancelled')),lease_until timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE support_ai_runs ENABLE ROW LEVEL SECURITY;REVOKE ALL ON support_ai_runs FROM PUBLIC,anon,authenticated;GRANT ALL ON support_ai_runs TO service_role;
CREATE OR REPLACE FUNCTION claim_support_run(p_actor uuid,p_conversation uuid,p_message uuid,p_epoch bigint,p_claim uuid) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE c conversations; found uuid;
BEGIN
 SELECT * INTO c FROM conversations WHERE id=p_conversation FOR UPDATE;
 IF c.id IS NULL OR c.course_id IS NOT NULL OR c.student_id<>p_actor OR c.status='closed' OR c.assistance_mode='HUMAN_SUPPORT' OR c.assistance_epoch<>p_epoch OR EXISTS(SELECT 1 FROM escalations WHERE conversation_id=c.id AND resolved_at IS NULL) OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=p_actor AND email_verified_at IS NOT NULL AND banned_at IS NULL AND(muted_until IS NULL OR muted_until<=now())) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM messages WHERE id=p_message AND conversation_id=c.id AND sender_id=p_actor AND sender_type='student') OR EXISTS(SELECT 1 FROM messages WHERE conversation_id=c.id AND sender_type='ai' AND meta->>'replyTo'=p_message::text) THEN RETURN false;END IF;
 INSERT INTO support_ai_runs(message_id,conversation_id,claim_id,epoch,status,lease_until)VALUES(p_message,c.id,p_claim,p_epoch,'processing',now()+interval '90 seconds') ON CONFLICT(message_id) DO UPDATE SET claim_id=p_claim,epoch=p_epoch,status='processing',lease_until=now()+interval '90 seconds' WHERE support_ai_runs.status='failed' OR(support_ai_runs.status='processing' AND support_ai_runs.lease_until<now()) RETURNING message_id INTO found;
 RETURN found IS NOT NULL;
END$$;
REVOKE ALL ON FUNCTION claim_support_run(uuid,uuid,uuid,bigint,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION claim_support_run(uuid,uuid,uuid,bigint,uuid) TO service_role;
CREATE OR REPLACE FUNCTION finish_support_run(p_actor uuid,p_conversation uuid,p_message uuid,p_claim uuid,p_body text,p_meta jsonb,p_issue jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE run support_ai_runs; m messages; saved boolean;
BEGIN
 PERFORM 1 FROM conversations WHERE id=p_conversation FOR UPDATE;
 SELECT * INTO run FROM support_ai_runs WHERE message_id=p_message AND conversation_id=p_conversation FOR UPDATE;
 IF run.claim_id IS DISTINCT FROM p_claim OR run.status<>'processing' OR run.lease_until<now() THEN RETURN false;END IF;
 saved:=commit_assistant_reply(p_actor,p_conversation,p_message,p_body,p_meta||jsonb_build_object('assistanceEpoch',run.epoch,'supportRun',p_claim));
 IF saved THEN
  SELECT * INTO m FROM messages WHERE id=p_message;
  INSERT INTO support_conversation_state(conversation_id,owner_id,issue,last_message_at,last_message_id)VALUES(p_conversation,p_actor,p_issue,m.created_at,m.id) ON CONFLICT(conversation_id)DO UPDATE SET issue=p_issue,last_message_at=m.created_at,last_message_id=m.id,updated_at=now() WHERE support_conversation_state.owner_id=p_actor AND support_conversation_state.last_message_at<=m.created_at;
 END IF;
 UPDATE support_ai_runs SET status=CASE WHEN saved THEN 'completed' ELSE 'cancelled' END WHERE message_id=p_message;
 RETURN saved;
END$$;
REVOKE ALL ON FUNCTION finish_support_run(uuid,uuid,uuid,uuid,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION finish_support_run(uuid,uuid,uuid,uuid,text,jsonb,jsonb) TO service_role;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('platform','Présentation de Faro School','presentation','Faro School propose des formations vidéo en ligne avec interface française et créole et une PWA.','{"procedure": "Consulter le catalogue Formations. Choisir une formation publiée pour connaître son contenu et ses conditions.", "conditions": "Compte et e-mail vérifiés pour les services privés. Les professeurs accompagnent leurs propres cours ; les administrateurs traitent le support du système.", "known_errors": "", "solutions": "Ne pas affirmer qu’une formation est disponible ou certifiante sans lire ses paramètres réels.", "links": ["/formations"]}','["src/lib/permissions.ts", "src/lib/auth/get-user.ts"]','support-kb-v1','published','student',now(),'4178e21bf465f4ccf6536cc21dd16abc07264a5d68ea5b6de6936a21619e0e98') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('accounts','Compte, connexion et sécurité','accounts','L’authentification utilise Auth.js, avec vérification d’e-mail avant l’accès aux pages protégées.','{"procedure": "Créer le compte, vérifier le code reçu, puis se connecter. Utiliser Mot de passe oublié sur la page de connexion pour demander un lien de réinitialisation. Les informations personnelles se modifient dans Profil et Paramètres.", "conditions": "Ne jamais communiquer mot de passe, code de connexion, code OTP ou PIN de paiement. Une suspension du chat ne signifie pas automatiquement suppression du compte ou des formations.", "known_errors": "", "solutions": "En cas d’erreur de connexion : vérifier l’adresse utilisée, utiliser la réinitialisation, indiquer uniquement le message d’erreur.", "links": ["/dashboard/profil/parametres"]}','["src/lib/auth/get-user.ts", "src/components/auth/LogoutButton.tsx"]','support-kb-v1','published','student',now(),'f41937d9b529c10621215aedbc873f37322219e8ffc996f5f51147901b4d2893') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('catalog','Catalogue et conditions d’accès','catalog','Les cours et leurs prix doivent être lus dans le catalogue publié de la base de données.','{"procedure": "Ouvrir Formations, sélectionner le cours et lire sa description, ses modules, son auteur et son tarif actuel.", "conditions": "Les brouillons ne sont pas des offres publiques. Les moyens de paiement peuvent être désactivés par formation. La devise des commandes est HTG. Aucune politique de remboursement ne doit être inventée.", "known_errors": "", "solutions": "Si la formation manque, vérifier sa publication avec les données du catalogue ; demander au support si l’accès attendu reste indisponible.", "links": ["/formations"]}','["src/app/api/payments/create/route.ts", "src/lib/messaging/data.ts"]','support-kb-v1','published','student',now(),'c5760ee2abc3f747a44bbf4eb9bbb564782ad10343bb5d499d20b86502409d0b') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('payments','Achat, paiement Kobara et diagnostic','payments','MonCash et NatCash passent par Kobara pour les moyens activés sur la formation. Le backend valide le montant et crée une commande pending.','{"procedure": "Depuis le catalogue, choisir Acheter, se connecter avec un e-mail vérifié, sélectionner le moyen activé puis suivre la redirection sécurisée Kobara. La confirmation fiable vient du backend. Pour une erreur, identifier le cours, l’étape avant/pendant/après paiement, le texte exact et si l’utilisateur indique un débit.", "conditions": "Ne pas recommander de payer à nouveau si un débit est signalé. Un débit déclaré n’est pas une confirmation backend. L’IA ne valide aucun paiement et n’accorde aucun accès. Les opérations de remboursement ou de correction nécessitent un administrateur.", "known_errors": "Codes réellement utilisés : provider_disabled (moyen désactivé), alreadyEnrolled (inscription déjà active), couponInvalid, rateLimit (429), order_write_unavailable, payment_lookup_unavailable, payment_binding_unavailable, gateway_auth (401/403 fournisseur), gateway_validation (400/422), gateway_rate_limited (429), gateway_unavailable, payment_checkout_unavailable, payment_checkout_invalid, payment_id_missing. Les trois erreurs de configuration ou de liaison nécessitent le support ; ne pas répéter le paiement. Statuts commande : pending, paid, failed, cancelled ; paiement : pending, awaiting_validation, validated, failed. Le retour du navigateur ne suffit pas à confirmer le paiement.", "solutions": "Codes réellement utilisés : provider_disabled (moyen désactivé), alreadyEnrolled (inscription déjà active), couponInvalid, rateLimit (429), order_write_unavailable, payment_lookup_unavailable, payment_binding_unavailable, gateway_auth (401/403 fournisseur), gateway_validation (400/422), gateway_rate_limited (429), gateway_unavailable, payment_checkout_unavailable, payment_checkout_invalid, payment_id_missing. Les trois erreurs de configuration ou de liaison nécessitent le support ; ne pas répéter le paiement. Statuts commande : pending, paid, failed, cancelled ; paiement : pending, awaiting_validation, validated, failed. Le retour du navigateur ne suffit pas à confirmer le paiement.", "links": ["/dashboard/paiements"]}','["src/app/api/payments/create/route.ts", "src/lib/payments/kobara.ts", "src/lib/payments/types.ts", "src/app/api/orders/[orderId]/status/route.ts"]','support-kb-v1','published','student',now(),'42306ec115bad86ff18f130a33e07415210219cc6643f227ac8444e921c7dffc') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('access','Retrouver et reprendre une formation','access','Le tableau de bord affiche les inscriptions du compte connecté et la progression enregistrée par le serveur.','{"procedure": "Ouvrir Mes formations, choisir le cours puis la leçon. Reprendre la leçon non terminée ou revoir une leçon déjà suivie. Si le cours manque après un paiement, lire les commandes et inscriptions du compte avant de conclure.", "conditions": "Une inscription révoquée ne donne plus accès. Les contenus privés exigent une autorisation côté serveur ; une capture d’écran de paiement seule n’accorde pas de droit.", "known_errors": "", "solutions": "Demander le titre du cours et le message exact ; comparer inscription active et statut de commande. En cas de paiement confirmé sans inscription active, demander un administrateur plutôt qu’un nouveau paiement.", "links": ["/dashboard/formations"]}','["src/lib/video/access.ts", "src/app/[locale]/(student)/dashboard/formations/page.tsx"]','support-kb-v1','published','student',now(),'6216de49ff5f9e70bb43d6976bfbad620c4896f6d207e6c7c266a7dd4f109feb') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('media','Lecteur vidéo et documents','media','Le lecteur utilise un iframe Bunny signé. Les ressources PDF privées passent par une route de téléchargement autorisée.','{"procedure": "Ouvrir le cours et la leçon depuis Mes formations. Vérifier la connexion et le bouton Lecture. Actualiser une fois, préciser le cours, la leçon, l’appareil et l’erreur. Pour un PDF, ouvrir Ressources puis le document disponible.", "conditions": "Ne jamais publier une URL signée de vidéo ou de document dans le support. Un problème de permission demande une vérification de l’inscription ; ne pas contourner le contrôle d’accès.", "known_errors": "", "solutions": "Si une tentative d’actualisation a déjà échoué, passer au diagnostic d’accès et à l’escalade au lieu de redonner la même procédure.", "links": ["/dashboard/formations"]}','["src/components/video/BunnyEmbedPlayer.tsx", "src/lib/video/access.ts", "src/app/api/video/resources/[resourceId]/download/route.ts"]','support-kb-v1','published','student',now(),'04bf279f96aa68144c2fa72494cc717d2360b6fd0a2996e1d7b083da4cb19a27') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('assessment','Quiz et certificats','assessment','Les quiz de leçon sont facultatifs et les notes sont calculées côté serveur. Le certificat suit les règles configurées sur le cours.','{"procedure": "Répondre au test facultatif lorsqu’il existe. Pour un certificat : inscription active, e-mail vérifié, pourcentage requis de leçons publiées terminé, certificat activé. Confirmer le nom avant la première émission puis télécharger depuis Certificats.", "conditions": "Le seuil par défaut est 100 %, mais le seuil réel et l’activation sont propres au cours. L’IA n’invente pas une note et ne délivre pas un certificat. Le nom imprimé est verrouillé après émission ; correction via administration. Le certificat reste en français.", "known_errors": "", "solutions": "Le remboursement ou la révocation de l’inscription peut révoquer le certificat. Lire son statut réel. Si le PDF ne se télécharge pas, transmettre la référence du certificat au support sans rendre le PDF public.", "links": ["/certificats"]}','["src/app/api/video/quiz/route.ts", "src/lib/certificates/service.ts", "supabase/migrations/20261029000000_certificates.sql"]','support-kb-v1','published','student',now(),'a6c75f02abe1bb64db89e34b698004e3507a7bca7e534cf6814a863e65be5e88') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('community','Messages, professeurs et communauté','community','La communauté et les messages ont des droits distincts. L’assistant pédagogique est rattaché au cours ; le support administratif concerne la plateforme.','{"procedure": "Pour un professeur : Messages, Écrire, choisir le professeur puis la formation suivie. La discussion utilise l’auteur responsable du cours. Pour le système : contacter la direction.", "conditions": "La communauté exige une inscription active. Les restrictions de mots et suspensions temporaires s’appliquent au chat. Les accès aux données privées restent limités aux participants autorisés.", "known_errors": "", "solutions": "Ne pas confondre une question de cours avec un problème de compte ou de paiement. Une question pédagogique hors contexte se transmet à l’auteur selon le flux existant.", "links": ["/dashboard/messages"]}','["src/app/actions/student-messaging.ts", "src/lib/messaging/recipients.ts", "supabase/migrations/20261030200000_community_entitlement.sql"]','support-kb-v1','published','student',now(),'434b67afe7fe938e376095d8b3e7ef3a911f6adb63d3b76391577a7d22003aa1') ON CONFLICT(slug)DO NOTHING;
INSERT INTO support_knowledge_articles(slug,title,category,description,content,source_refs,system_version,validation_status,visibility,reviewed_at,source_version)VALUES('support','Support humain et tickets','support','L’assistant support explique les procédures vérifiées et peut lire les informations autorisées du compte courant.','{"procedure": "Décrire le problème. Si une action administrative est nécessaire, demander un transfert. Le bouton Créer un ticket support déclenche une demande explicite ; le numéro n’est annoncé qu’après enregistrement confirmé.", "conditions": "Pendant un ticket actif, l’IA s’arrête et l’élève peut continuer à écrire au support humain. Résoudre le ticket autorise la reprise de l’IA. Les conversations et leurs messages ne sont pas supprimés.", "known_errors": "", "solutions": "Un administrateur peut répondre plus tard s’il est hors ligne. Ne pas affirmer qu’un message a été lu ou qu’un e-mail a été livré sans accusé correspondant.", "links": ["/dashboard/messages"]}','["src/app/actions/private-messaging.ts", "supabase/migrations/20261102230000_live_messaging_sessions.sql"]','support-kb-v1','published','student',now(),'cc009f4191368bf7386fbe7ff49339e74d314114e26dc5ed9e1cdbeb35752a4c') ON CONFLICT(slug)DO NOTHING;
CREATE OR REPLACE FUNCTION open_support_ticket(p_actor uuid,p_conversation uuid,p_message uuid,p_claim uuid,p_issue jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE c conversations; run support_ai_runs; result jsonb; m messages;
BEGIN
 SELECT * INTO c FROM conversations WHERE id=p_conversation FOR UPDATE;
 SELECT * INTO run FROM support_ai_runs WHERE message_id=p_message AND conversation_id=c.id FOR UPDATE;
 IF c.student_id IS DISTINCT FROM p_actor OR c.course_id IS NOT NULL OR c.assistance_epoch<>run.epoch OR run.claim_id IS DISTINCT FROM p_claim OR run.status<>'processing' OR run.lease_until<now() THEN RAISE EXCEPTION 'forbidden';END IF;
 result:=queue_assistant_handoff(p_actor,c.id,p_message,'support_human_request','',jsonb_build_object('supportTicketRequested',true,'assistantMode','support'));
 SELECT * INTO m FROM messages WHERE id=p_message;
 INSERT INTO support_conversation_state(conversation_id,owner_id,issue,last_message_at,last_message_id)VALUES(c.id,p_actor,p_issue||'{"transferOffered":false}',m.created_at,m.id) ON CONFLICT(conversation_id)DO UPDATE SET issue=excluded.issue,last_message_at=excluded.last_message_at,last_message_id=excluded.last_message_id,updated_at=now() WHERE support_conversation_state.owner_id=p_actor AND support_conversation_state.last_message_at<=m.created_at;
 UPDATE support_ai_runs SET status='completed' WHERE message_id=p_message;
 RETURN result;
END$$;
REVOKE ALL ON FUNCTION open_support_ticket(uuid,uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION open_support_ticket(uuid,uuid,uuid,uuid,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION save_support_article(p_actor uuid,p_id uuid,p_expected int,p_article jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE old support_knowledge_articles; result support_knowledge_articles; verified boolean:=coalesce((p_article->>'verified')::boolean,false);
BEGIN
 IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=p_actor AND role='admin' AND email_verified_at IS NOT NULL AND banned_at IS NULL) THEN RAISE EXCEPTION 'forbidden';END IF;
 IF p_article->>'validation_status' IN('validated','published') AND NOT verified THEN RAISE EXCEPTION 'review_required';END IF;
 IF jsonb_array_length(p_article->'source_refs')<1 THEN RAISE EXCEPTION 'source_required';END IF;
 IF p_id IS NOT NULL THEN
  SELECT * INTO old FROM support_knowledge_articles WHERE id=p_id FOR UPDATE;
  IF old.id IS NULL OR old.revision<>p_expected THEN RAISE EXCEPTION 'revision_conflict';END IF;
  INSERT INTO support_knowledge_versions(article_id,revision,snapshot)VALUES(old.id,old.revision,to_jsonb(old)) ON CONFLICT DO NOTHING;
  UPDATE support_knowledge_articles SET slug=p_article->>'slug',title=p_article->>'title',category=p_article->>'category',language=p_article->>'language',description=p_article->>'description',content=p_article->'content',source_refs=p_article->'source_refs',source_version=p_article->>'source_version',system_version=p_article->>'system_version',validation_status=p_article->>'validation_status',visibility=p_article->>'visibility',revision=old.revision+1,reviewed_at=CASE WHEN verified THEN now() END,reviewed_by=CASE WHEN verified THEN p_actor END,updated_at=now() WHERE id=old.id RETURNING * INTO result;
 ELSE
  INSERT INTO support_knowledge_articles(slug,title,category,language,description,content,source_refs,source_version,system_version,validation_status,visibility,reviewed_at,reviewed_by)VALUES(p_article->>'slug',p_article->>'title',p_article->>'category',p_article->>'language',p_article->>'description',p_article->'content',p_article->'source_refs',p_article->>'source_version',p_article->>'system_version',p_article->>'validation_status',p_article->>'visibility',CASE WHEN verified THEN now() END,CASE WHEN verified THEN p_actor END)RETURNING * INTO result;
 END IF;
 INSERT INTO admin_audit_logs(admin_id,action,target_id,reason,details)VALUES(p_actor,'support_knowledge_'||result.validation_status,result.id::text,'Knowledge article review',jsonb_build_object('revision',result.revision,'visibility',result.visibility));
 RETURN to_jsonb(result);
END$$;
REVOKE ALL ON FUNCTION save_support_article(uuid,uuid,int,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION save_support_article(uuid,uuid,int,jsonb) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;
